static inline raw_spinlock_t *lock_addr(const atomic64_t *v) /* <=== lock_addr */ 
{
	unsigned long addr = (unsigned long) v;

	addr >>= L1_CACHE_SHIFT;
	addr ^= (addr >> 8) ^ (addr >> 16);
	return &atomic64_lock[addr & (NR_LOCKS - 1)].lock;
}

static inline void percpu_counter_inc(struct percpu_counter *fbc) /* <=== percpu_counter_inc */ 
{
	percpu_counter_add(fbc, 1);
}

static inline void atomic64_set(atomic64_t *v, long long i) /* <=== atomic64_set */ 
{
	unsigned high = (unsigned)(i >> 32);
	unsigned low = (unsigned)i;
	alternative_atomic64(set, /* no output */,
			     "S" (v), "b" (low), "c" (high)
			     : "eax", "edx", "memory");
}

static inline void sock_reset_flag(struct sock *sk, enum sock_flags flag) /* <=== sock_reset_flag */ 
